mkdir -p src; cat > src/system.poly <<'EOF'
module consensus

enum Role { follower, candidate, leader, shutdown }

machine Node {
  state {
    role : Role = follower
    term : 0..3 = 0
  }
  terminal role == shutdown

  action ElectionTimeout()
  action ElectionWon()
  action NewerTermSeen(t: 1..3)
  action QuorumLost()
  action Shutdown()

  on ElectionTimeout {
    require role != shutdown else reject "shut-down"
    require role != leader else reject "is-leader"
    require term < 3 else reject "last-term"
    role' = candidate
    term' = term + 1
  }
  on ElectionWon {
    require role != shutdown else reject "shut-down"
    require role == candidate else reject "not-candidate"
    role' = leader
  }
  on NewerTermSeen(t) {
    require role != shutdown else reject "shut-down"
    require t > term else reject "not-newer"
    role' = follower
    term' = t
  }
  on QuorumLost {
    require role != shutdown else reject "shut-down"
    require role == leader else reject "not-leader"
    role' = follower
  }
  on Shutdown {
    require role != shutdown else reject "shut-down"
    role' = shutdown
  }

  step property term-never-decreases: post.term >= pre.term
  step property term-changes-by-election-or-newer-term:
    post.term != pre.term implies (action == ElectionTimeout || action == NewerTermSeen)
  step property leader-was-candidate:
    (post.role == leader && pre.role != leader) implies (pre.role == candidate && pre.term == post.term)
  step property shutdown-is-final: pre.role == shutdown implies post.role == shutdown
}
EOF
cat > host.map.json <<'EOF'
{
  "module": "src/system.poly",
  "instances": { "node": { "machine": "Node" } },
  "methods": {
    "electionTimeout": { "instance": "node", "action": "ElectionTimeout" },
    "electionWon": { "instance": "node", "action": "ElectionWon" },
    "newerTermSeen": { "instance": "node", "action": "NewerTermSeen", "params": { "t": "$arg:term" } },
    "quorumLost": { "instance": "node", "action": "QuorumLost" },
    "shutdown": { "instance": "node", "action": "Shutdown" }
  },
  "queries": { "node": { "instance": "node", "fields": { "role": "role", "term": "term" } } }
